# mk_sub2.py GROUPFILE STATE OUTSTATE GROUPOUT gen1 [gen2 ...]: lift state of an abelian group G over the subgroup H
# generated by the given element indices (G table indices). Writes the H table (identity 0) to GROUPOUT and the state.
import sys
gf, sf, outp, gout = sys.argv[1], sys.argv[2], sys.argv[3], sys.argv[4]; gens = [int(s) for s in sys.argv[5:]]
L = open(gf).read().split(); N = int(L[0]); T = [[int(L[1 + a * N + b]) for b in range(N)] for a in range(N)]
S = open(sf).read().split('\n'); NN, k = map(int, S[0].split())
E = [tuple(map(int, l.split())) for l in S[1:] if l.strip()]
assert NN == N
H = [0]; seen = {0}; i = 0
while i < len(H):
    x = H[i]; i += 1
    for g in gens:
        y = T[x][g]
        if y not in seen: seen.add(y); H.append(y)
hn = len(H); hidx = {h: i for i, h in enumerate(H)}
with open(gout, 'w') as f:
    f.write(f"{hn}\n")
    for a in H: f.write(" ".join(str(hidx[T[a][b]]) for b in H) + "\n")
# coset decomposition
reps = [0]; cos = {}
for h in H: cos[h] = (0, hidx[h])
for g in range(N):
    if g in cos: continue
    reps.append(g)
    for h in H: cos[T[g][h]] = (len(reps) - 1, hidx[h])
C = len(reps); assert C * hn == N
out = [f"{hn} {C * k}"]
for (u, v, a) in E:
    for c in range(C):
        d, j = cos[T[reps[c]][a]]
        out.append(f"{u * C + c} {v * C + d} {j}")
open(outp, 'w').write('\n'.join(out) + '\n')
print("H order", hn, "cosets", C, "new k", C * k, "base edges", len(out) - 1)
